  cme = `Tomrom i diagrammet (f.eks. mellom %1$s og %2$s bilder per sekund) kan skyldes VSync, som synkroniserer bildelevering med skjermens oppdateringsfrekvens for å forhindre skjermriving. Dette kan føre til at målinger hoper seg opp på %1$s og %2$s bilder per sekund, selv om spillets gjennomsnittlige bildefrekvens ligger mellom dem. Dette er normal atferd med VSync, og selv om det kan gå ut over bildelevering, betyr det ikke nødvendigvis at det oppstår merkbar hakking.`,
